// ListContactGroups returns all legacy contact_groups rows for the given
// organization_id, including members. Two queries: one for groups, one
// for members joined back.
func (r *PostgresReader) ListContactGroups(ctx context.Context, legacyOrgID string) ([]LegacyContactGroup, error) {
	if legacyOrgID == "" {
		return nil, errors.New("legacy: legacyOrgID required for ListContactGroups")
	}
	const gq = `
SELECT id, COALESCE(name, ''), COALESCE(description, ''), COALESCE(color, '')
  FROM contact_groups
 WHERE organization_id = $1
 ORDER BY id`

	rows, err := r.pool.Query(ctx, gq, legacyOrgID)
	if err != nil {
		return nil, fmt.Errorf("legacy: ListContactGroups query: %w", err)
	}
	defer rows.Close()

	groupIndex := map[string]int{}
	var groups []LegacyContactGroup
	for rows.Next() {
		var g LegacyContactGroup
		if err := rows.Scan(&g.LegacyID, &g.Name, &g.Description, &g.Color); err != nil {
			return nil, fmt.Errorf("legacy: ListContactGroups scan: %w", err)
		}
		groupIndex[g.LegacyID] = len(groups)
		groups = append(groups, g)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("legacy: ListContactGroups rows: %w", err)
	}
	if len(groups) == 0 {
		return nil, nil
	}

	const mq = `
SELECT group_id, contact_id, COALESCE(added_at, NOW())
  FROM contact_group_members
 WHERE organization_id = $1
 ORDER BY group_id, contact_id`

	mrows, err := r.pool.Query(ctx, mq, legacyOrgID)
	if err != nil {
		return nil, fmt.Errorf("legacy: ListContactGroups members query: %w", err)
	}
	defer mrows.Close()

	for mrows.Next() {
		var groupID, contactID string
		var addedAt time.Time
		if err := mrows.Scan(&groupID, &contactID, &addedAt); err != nil {
			return nil, fmt.Errorf("legacy: ListContactGroups members scan: %w", err)
		}
		if idx, ok := groupIndex[groupID]; ok {
			groups[idx].Members = append(groups[idx].Members, LegacyContactGroupMember{
				ContactLegacyID: contactID,
				AddedAt:         addedAt.UTC(),
			})
		}
	}
	if err := mrows.Err(); err != nil {
		return nil, fmt.Errorf("legacy: ListContactGroups members rows: %w", err)
	}
	return groups, nil
}

