// ListConversations returns all legacy conversations for the given org.
func (r *PostgresReader) ListConversations(ctx context.Context, legacyOrgID string) ([]LegacyConversation, error) {
	if legacyOrgID == "" {
		return nil, errors.New("legacy: legacyOrgID required for ListConversations")
	}
	const q = `
SELECT id, channel_id, COALESCE(is_group, false),
       COALESCE(contact_id, ''), COALESCE(external_thread_id, ''),
       COALESCE(title, ''), COALESCE(status, 'open'), COALESCE(priority, 0),
       COALESCE(last_message_at, created_at), created_at
  FROM conversations
 WHERE organization_id = $1
 ORDER BY id`

	rows, err := r.pool.Query(ctx, q, legacyOrgID)
	if err != nil {
		return nil, fmt.Errorf("legacy: ListConversations query: %w", err)
	}
	defer rows.Close()

	var out []LegacyConversation
	for rows.Next() {
		var c LegacyConversation
		var lastMsgAt, createdAt time.Time
		if err := rows.Scan(
			&c.LegacyID, &c.ChannelLegacyID, &c.IsGroup,
			&c.ContactLegacyID, &c.ExternalThreadID,
			&c.Title, &c.Status, &c.Priority,
			&lastMsgAt, &createdAt,
		); err != nil {
			return nil, fmt.Errorf("legacy: ListConversations scan: %w", err)
		}
		c.LastMessageAt = lastMsgAt.UTC()
		c.CreatedAt = createdAt.UTC()
		out = append(out, c)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("legacy: ListConversations rows: %w", err)
	}
	// Fetch group participants in a single batched query (avoids an N+1 over
	// group conversations). Collect the group conversation IDs and map each to
	// its index in out so rows can be grouped to the right conversation.
	var groupIDs []string
	idx := make(map[string]int, len(out))
	for i, conv := range out {
		if !conv.IsGroup {
			continue
		}
		groupIDs = append(groupIDs, conv.LegacyID)
		idx[conv.LegacyID] = i
	}
	if len(groupIDs) > 0 {
		const pq = `
SELECT conversation_id, contact_id
  FROM conversation_participants
 WHERE conversation_id = ANY($1)
 ORDER BY conversation_id, contact_id`
		prows, err := r.pool.Query(ctx, pq, groupIDs)
		if err != nil {
			return nil, fmt.Errorf("legacy: ListConversations participants: %w", err)
		}
		for prows.Next() {
			var convID, cid string
			if err := prows.Scan(&convID, &cid); err != nil {
				prows.Close()
				return nil, fmt.Errorf("legacy: ListConversations participants scan: %w", err)
			}
			i := idx[convID]
			out[i].ParticipantContactLegacyIDs = append(out[i].ParticipantContactLegacyIDs, cid)
		}
		prows.Close()
		if err := prows.Err(); err != nil {
			return nil, fmt.Errorf("legacy: ListConversations participants rows: %w", err)
		}
	}
	return out, nil
}

// ListMessages returns a page of legacy messages for the given org.
// afterID is the last seen message id (empty = from beginning).
// limit is the page size.
func (r *PostgresReader) ListMessages(ctx context.Context, legacyOrgID string, afterID string, limit int) ([]LegacyMessage, error) {
	if legacyOrgID == "" {
		return nil, errors.New("legacy: legacyOrgID required for ListMessages")
	}
	if limit <= 0 {
		limit = 1000
	}
	const q = `
SELECT id, conversation_id,
       COALESCE(direction, 'inbound'),
       COALESCE(status, 'received'),
       COALESCE(sender_user_id, ''),
       COALESCE(sender_contact_id, ''),
       COALESCE(body, ''),
       COALESCE(body_html, ''),
       COALESCE(external_id, ''),
       COALESCE(sent_at, created_at),
       COALESCE(received_at, created_at)
  FROM messages
 WHERE organization_id = $1
   AND ($2 = '' OR id > $2)
 ORDER BY id
 LIMIT $3`

	rows, err := r.pool.Query(ctx, q, legacyOrgID, afterID, limit)
	if err != nil {
		return nil, fmt.Errorf("legacy: ListMessages query: %w", err)
	}
	defer rows.Close()

	var out []LegacyMessage
	for rows.Next() {
		var m LegacyMessage
		var sentAt, receivedAt time.Time
		if err := rows.Scan(
			&m.LegacyID, &m.ConversationLegacyID,
			&m.Direction, &m.Status,
			&m.SenderLegacyUserID, &m.SenderContactLegacyID,
			&m.Body, &m.BodyHTML, &m.ExternalID,
			&sentAt, &receivedAt,
		); err != nil {
			return nil, fmt.Errorf("legacy: ListMessages scan: %w", err)
		}
		m.SentAt = sentAt.UTC()
		m.ReceivedAt = receivedAt.UTC()
		out = append(out, m)
	}
	return out, rows.Err()
}

// ListAttachments returns all legacy message_attachments for the given org.
func (r *PostgresReader) ListAttachments(ctx context.Context, legacyOrgID string) ([]LegacyAttachment, error) {
	if legacyOrgID == "" {
		return nil, errors.New("legacy: legacyOrgID required for ListAttachments")
	}
	const q = `
SELECT a.id, a.message_id, COALESCE(a.filename, ''),
       COALESCE(a.mime_type, 'application/octet-stream'),
       COALESCE(a.file_path, '')
  FROM message_attachments a
  JOIN messages m ON m.id = a.message_id
 WHERE m.organization_id = $1
 ORDER BY a.id`

	rows, err := r.pool.Query(ctx, q, legacyOrgID)
	if err != nil {
		return nil, fmt.Errorf("legacy: ListAttachments query: %w", err)
	}
	defer rows.Close()

	var out []LegacyAttachment
	for rows.Next() {
		var a LegacyAttachment
		if err := rows.Scan(
			&a.LegacyID, &a.MessageLegacyID,
			&a.Filename, &a.MIMEType, &a.FilesystemPath,
		); err != nil {
			return nil, fmt.Errorf("legacy: ListAttachments scan: %w", err)
		}
		out = append(out, a)
	}
	return out, rows.Err()
}

