// ListShares returns all legacy channel shares for the given org,
// grouped by channel.
func (r *PostgresReader) ListShares(ctx context.Context, legacyOrgID string) ([]LegacyShare, error) {
	if legacyOrgID == "" {
		return nil, errors.New("legacy: legacyOrgID required for ListShares")
	}
	const q = `
SELECT id, COALESCE(visibility, 'private')
  FROM dialogue_channels
 WHERE organization_id = $1
 ORDER BY id`

	rows, err := r.pool.Query(ctx, q, legacyOrgID)
	if err != nil {
		return nil, fmt.Errorf("legacy: ListShares channels query: %w", err)
	}
	defer rows.Close()

	shareIndex := map[string]int{}
	var shares []LegacyShare
	for rows.Next() {
		var s LegacyShare
		if err := rows.Scan(&s.ChannelLegacyID, &s.Visibility); err != nil {
			return nil, fmt.Errorf("legacy: ListShares scan: %w", err)
		}
		shareIndex[s.ChannelLegacyID] = len(shares)
		shares = append(shares, s)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("legacy: ListShares rows: %w", err)
	}

	const gq = `
SELECT cs.channel_id, cs.user_id, COALESCE(cs.role, 'viewer')
  FROM channel_shares cs
  JOIN dialogue_channels dc ON dc.id = cs.channel_id
 WHERE dc.organization_id = $1
 ORDER BY cs.channel_id, cs.user_id`

	grows, err := r.pool.Query(ctx, gq, legacyOrgID)
	if err != nil {
		return nil, fmt.Errorf("legacy: ListShares grants query: %w", err)
	}
	defer grows.Close()

	for grows.Next() {
		var channelID, userID, role string
		if err := grows.Scan(&channelID, &userID, &role); err != nil {
			return nil, fmt.Errorf("legacy: ListShares grants scan: %w", err)
		}
		if idx, ok := shareIndex[channelID]; ok {
			shares[idx].Grants = append(shares[idx].Grants, LegacyShareGrant{
				UserLegacyID: userID,
				Role:         role,
			})
		}
	}
	return shares, grows.Err()
}

// ListRecipes returns all legacy dialogue_recipes for the given org.
// trigger_config / action_config jsonb are cast to text and surfaced as
// raw JSON []byte; the channel and created_by FKs are cast to text so
// legacy int PKs/FKs survive as strings.
func (r *PostgresReader) ListRecipes(ctx context.Context, legacyOrgID string) ([]LegacyRecipe, error) {
	if legacyOrgID == "" {
		return nil, errors.New("legacy: legacyOrgID required for ListRecipes")
	}
	const q = `
SELECT id::text,
       COALESCE(name, ''),
       COALESCE(description, ''),
       COALESCE(is_active, true),
       COALESCE(trigger_type, 'message_received'),
       COALESCE(trigger_config, '{}'::jsonb)::text,
       COALESCE(action_type, 'send_message'),
       COALESCE(action_config, '{}'::jsonb)::text,
       COALESCE(channel_id::text, ''),
       COALESCE(channel_type, ''),
       COALESCE(max_executions_per_contact, 0),
       COALESCE(cooldown_minutes, 0),
       COALESCE(created_by::text, ''),
       created_at
  FROM dialogue_recipes
 WHERE organization_id = $1
 ORDER BY id`

	rows, err := r.pool.Query(ctx, q, legacyOrgID)
	if err != nil {
		return nil, fmt.Errorf("legacy: ListRecipes query: %w", err)
	}
	defer rows.Close()

	var out []LegacyRecipe
	for rows.Next() {
		var rec LegacyRecipe
		var triggerCfg, actionCfg string
		var createdAt time.Time
		if err := rows.Scan(
			&rec.LegacyID,
			&rec.Name,
			&rec.Description,
			&rec.IsActive,
			&rec.TriggerType,
			&triggerCfg,
			&rec.ActionType,
			&actionCfg,
			&rec.ChannelLegacyID,
			&rec.ChannelType,
			&rec.MaxExecutionsPerContact,
			&rec.CooldownMinutes,
			&rec.CreatedByLegacyID,
			&createdAt,
		); err != nil {
			return nil, fmt.Errorf("legacy: ListRecipes scan: %w", err)
		}
		rec.TriggerConfig = []byte(triggerCfg)
		rec.ActionConfig = []byte(actionCfg)
		rec.CreatedAt = createdAt.UTC()
		out = append(out, rec)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("legacy: ListRecipes rows: %w", err)
	}
	return out, nil
}


