// Package legacy contains DTOs for the legacy Dialogue Postgres schema.
// The PostgresReader is strictly read-only; production deployments connect
// with the migrator_ro role to enforce that at the database level.
package legacy

import (
	"context"
	"time"
)

// LegacyChannel is a row from legacy dialogue_channels.
type LegacyChannel struct {
	LegacyID    string    // legacy dialogue_channels.id (UUID or TEXT PK)
	OrgID       string    // legacy dialogue_channels.organization_id
	Type        string    // legacy channel type string, e.g. "email", "telegram_bot", "whatsapp"
	Name        string    // legacy dialogue_channels.name
	OwnerUserID string    // legacy dialogue_channels.owner_user_id (may be empty)
	Config      []byte    // legacy dialogue_channels.config (raw JSON)
	IsDefault   bool      // legacy dialogue_channels.is_default
	CreatedAt   time.Time // legacy dialogue_channels.created_at
}

// ChannelReader is the legacy-Postgres subset for the channels phase.
// Tests inject a mock; production uses the pgxpool-backed PostgresReader.
type ChannelReader interface {
	ListChannels(ctx context.Context, legacyOrgID string) ([]LegacyChannel, error)
}

// LegacyContact is a row from legacy contacts.
type LegacyContact struct {
	LegacyID         string    // legacy contacts.id
	ChannelLegacyID  string    // legacy contacts.channel_id (FK to dialogue_channels)
	Identifier       string    // legacy contacts.identifier (email, phone, tg user_id, etc.)
	DisplayName      string    // legacy contacts.display_name
	Properties       []byte    // legacy contacts.properties (raw JSON)
	CreatedAt        time.Time // legacy contacts.created_at
}

// ContactReader is the legacy-Postgres subset for the contacts phase.
type ContactReader interface {
	ListContacts(ctx context.Context, legacyOrgID string) ([]LegacyContact, error)
}

// LegacyContactGroupMember is one member of a legacy contact group.
type LegacyContactGroupMember struct {
	ContactLegacyID string
	AddedAt         time.Time
}

// LegacyContactGroup is a row from legacy contact_groups with members.
type LegacyContactGroup struct {
	LegacyID    string
	Name        string
	Description string
	Color       string
	Members     []LegacyContactGroupMember
}

// ContactGroupReader is the legacy-Postgres subset for the contact-groups phase.
type ContactGroupReader interface {
	ListContactGroups(ctx context.Context, legacyOrgID string) ([]LegacyContactGroup, error)
}

// LegacyTemplate is a row from legacy templates.
type LegacyTemplate struct {
	LegacyID          string
	Name              string
	Category          string // e.g. "general", "support", "sales"
	Content           string
	CreatedByLegacyID string
	CreatedAt         time.Time
}

// TemplateReader is the legacy-Postgres subset for the templates phase.
type TemplateReader interface {
	ListTemplates(ctx context.Context, legacyOrgID string) ([]LegacyTemplate, error)
}

// LegacyConversation is a row from legacy conversations.
type LegacyConversation struct {
	LegacyID                    string
	ChannelLegacyID             string
	IsGroup                     bool
	ContactLegacyID             string    // empty for group conversations
	ExternalThreadID            string
	Title                       string
	Status                      string    // e.g. "open", "closed", "pending"
	Priority                    int32
	LastMessageAt               time.Time
	ParticipantContactLegacyIDs []string  // for is_group=true
	CreatedAt                   time.Time
}

// ConversationReader is the legacy-Postgres subset for the conversations phase.
type ConversationReader interface {
	ListConversations(ctx context.Context, legacyOrgID string) ([]LegacyConversation, error)
}

// LegacyMessage is a row from legacy messages. Paginated by id.
type LegacyMessage struct {
	LegacyID                   string
	ConversationLegacyID       string
	Direction                  string    // "inbound" | "outbound"
	Status                     string    // terminal only: "sent" | "received"
	SenderLegacyUserID         string    // set for outbound (operator user)
	SenderContactLegacyID      string    // set for inbound (contact)
	Body                       string
	BodyHTML                   string
	ExternalID                 string
	SentAt                     time.Time
	ReceivedAt                 time.Time
}

// MessageReader is the legacy-Postgres subset for the messages phase.
// ListMessages accepts a cursor (last seen id) for pagination.
type MessageReader interface {
	ListMessages(ctx context.Context, legacyOrgID string, afterID string, limit int) ([]LegacyMessage, error)
}

// LegacyAttachment is metadata for a legacy message attachment stored on
// a legacy filesystem. The go side opens a client-streaming RPC per row.
type LegacyAttachment struct {
	LegacyID            string
	MessageLegacyID     string
	Filename            string
	MIMEType            string
	FilesystemPath      string // absolute path on legacy filesystem
}

// AttachmentReader is the legacy-Postgres subset for the attachments phase.
type AttachmentReader interface {
	ListAttachments(ctx context.Context, legacyOrgID string) ([]LegacyAttachment, error)
}

// LegacyNote is a row from legacy analyst_notes.
type LegacyNote struct {
	LegacyID                  string
	ConversationLegacyID      string
	AuthorLegacyUserID        string
	Body                      string
	CreatedAt                 time.Time
}

// NoteReader is the legacy-Postgres subset for the notes phase.
type NoteReader interface {
	ListNotes(ctx context.Context, legacyOrgID string) ([]LegacyNote, error)
}

// LegacyTag is a row from legacy conversation_tags.
type LegacyTag struct {
	ConversationLegacyID   string
	Tag                    string
	TaggedByLegacyUserID   string
	TaggedAt               time.Time
}

// TagReader is the legacy-Postgres subset for the tags phase.
type TagReader interface {
	ListTags(ctx context.Context, legacyOrgID string) ([]LegacyTag, error)
}

// LegacyShareGrant is one user grant within a legacy channel share.
type LegacyShareGrant struct {
	UserLegacyID string
	Role         string // "viewer" | "editor" | "admin"
}

// LegacyShare groups the visibility + grants for one channel.
type LegacyShare struct {
	ChannelLegacyID string
	Visibility      string             // "private" | "shared" | "public"
	Grants          []LegacyShareGrant // only populated for visibility="shared"
}

// ShareReader is the legacy-Postgres subset for the shares phase.
type ShareReader interface {
	ListShares(ctx context.Context, legacyOrgID string) ([]LegacyShare, error)
}

// LegacyRecipe is a row from legacy dialogue_recipes.
type LegacyRecipe struct {
	LegacyID                string
	Name                    string
	Description             string
	IsActive                bool
	TriggerType             string
	TriggerConfig           []byte // raw JSON
	ActionType              string
	ActionConfig            []byte // raw JSON
	ChannelLegacyID         string // FK dialogue_channels, nullable
	ChannelType             string
	MaxExecutionsPerContact int
	CooldownMinutes         int
	CreatedByLegacyID       string // FK users
	CreatedAt               time.Time
}

// RecipeReader is the legacy-Postgres subset for the recipes phase.
type RecipeReader interface {
	ListRecipes(ctx context.Context, legacyOrgID string) ([]LegacyRecipe, error)
}



