//go:build integration

package legacy_test

import (
	"context"
	"testing"

	"github.com/jackc/pgx/v5/pgxpool"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/zenithflowinc/omnicore-platform/services/migrator-dialogue/internal/legacy"
)

// TestPostgresReader_ListConversations_GroupsParticipantsToRightConversation
// is a characterization (correctness-guard) test for the participant-grouping
// behavior of ListConversations.
//
// CR-M12 replaces the current per-group-conversation N+1 participant query
// with ONE batched query (WHERE conversation_id = ANY($1)), grouped in
// memory. The observable output MUST be identical: each group conversation's
// ParticipantContactLegacyIDs is the ordered list of its participants'
// contact_ids (ORDER BY contact_id), and non-group conversations get none.
//
// This test seeds, under an org isolated from the shared fixture's
// legacy-org-001 rows:
//   - G1 (is_group=true)  with participants [cr-m12-cB, cr-m12-cA, cr-m12-cC]
//     INSERTED OUT OF ORDER to exercise the query's ORDER BY contact_id.
//   - G2 (is_group=true)  with a single participant [cr-m12-cX].
//   - S1 (is_group=false) with NO participant rows.
//
// It asserts the grouping maps each contact to the RIGHT conversation in the
// RIGHT order. It should PASS on the current (slow but correct) code and KEEP
// passing after the batched rewrite — guarding against a regression where
// participants are assigned to the wrong conversation, dropped, or mis-ordered.
func TestPostgresReader_ListConversations_GroupsParticipantsToRightConversation(t *testing.T) {
	if testing.Short() {
		t.Skip("integration test skipped in short mode")
	}
	ctx := context.Background()

	// Boot the shared legacy-Postgres testcontainer (fixture applied). We seed
	// our own rows under a DISTINCT org so they are isolated from the fixture's
	// legacy-org-001 conversations — ListConversations filters by org.
	dsn := startLegacyPostgres(t)

	const orgID = "cr-m12-org"
	seedParticipantGroupingFixture(t, ctx, dsn, orgID)

	reader, err := legacy.NewPostgresReader(ctx, dsn)
	require.NoError(t, err)
	defer reader.Close()

	convs, err := reader.ListConversations(ctx, orgID)
	require.NoError(t, err)

	// The three seeded conversations must come back (ORDER BY id => G1, G2, S1).
	require.Len(t, convs, 3, "exactly the 3 seeded conversations for %s", orgID)
	byID := map[string]legacy.LegacyConversation{}
	for _, c := range convs {
		byID[c.LegacyID] = c
	}
	require.Contains(t, byID, "cr-m12-G1")
	require.Contains(t, byID, "cr-m12-G2")
	require.Contains(t, byID, "cr-m12-S1")

	// G1: three participants, returned sorted by contact_id (ORDER BY contact_id),
	// NOT the out-of-order insert order [cB, cA, cC].
	assert.Equal(t,
		[]string{"cr-m12-cA", "cr-m12-cB", "cr-m12-cC"},
		byID["cr-m12-G1"].ParticipantContactLegacyIDs,
		"G1 participants must be its own contacts, sorted by contact_id",
	)

	// G2: exactly its single participant — not bleeding G1's contacts.
	assert.Equal(t,
		[]string{"cr-m12-cX"},
		byID["cr-m12-G2"].ParticipantContactLegacyIDs,
		"G2 must carry only its own single participant",
	)

	// S1: non-group conversation gets no participants.
	assert.Empty(t,
		byID["cr-m12-S1"].ParticipantContactLegacyIDs,
		"non-group conversation must have no participants",
	)
}

// seedParticipantGroupingFixture opens a direct pgxpool against the
// testcontainer DSN and inserts the channel, contacts, conversations, and
// out-of-order participant rows under orgID. The legacy schema's FKs
// (conversations.channel_id -> dialogue_channels, conversation_participants
// .contact_id -> contacts) require the parent rows to exist first.
func seedParticipantGroupingFixture(t *testing.T, ctx context.Context, dsn, orgID string) {
	t.Helper()

	pool, err := pgxpool.New(ctx, dsn)
	require.NoError(t, err, "open seed pgxpool")
	t.Cleanup(pool.Close)

	const channelID = "cr-m12-chan-001"
	_, err = pool.Exec(ctx, `
INSERT INTO dialogue_channels (id, organization_id, type, name)
VALUES ($1, $2, 'email', 'CR-M12 Channel')`, channelID, orgID)
	require.NoError(t, err, "seed channel")

	// Four contacts. Insert ids out of order to be safe; ORDER BY in the query
	// is what we are pinning, not insert order.
	for _, cid := range []string{"cr-m12-cB", "cr-m12-cA", "cr-m12-cC", "cr-m12-cX"} {
		_, err = pool.Exec(ctx, `
INSERT INTO contacts (id, organization_id, channel_id, identifier, display_name)
VALUES ($1, $2, $3, $1, $1)`, cid, orgID, channelID)
		require.NoError(t, err, "seed contact %s", cid)
	}

	// G1 + G2 are group conversations; S1 is a 1:1 (non-group) conversation.
	_, err = pool.Exec(ctx, `
INSERT INTO conversations (id, organization_id, channel_id, is_group, contact_id, title)
VALUES
  ('cr-m12-G1', $1, $2, true,  NULL,         'Group One'),
  ('cr-m12-G2', $1, $2, true,  NULL,         'Group Two'),
  ('cr-m12-S1', $1, $2, false, 'cr-m12-cA',  '')`, orgID, channelID)
	require.NoError(t, err, "seed conversations")

	// G1 participants inserted OUT OF ORDER ([cB, cA, cC]) so the assertion on
	// sorted output [cA, cB, cC] proves ORDER BY contact_id is honoured.
	// G2 gets a single participant; S1 gets none.
	_, err = pool.Exec(ctx, `
INSERT INTO conversation_participants (conversation_id, contact_id)
VALUES
