package legacy

import (
	"context"
	"errors"
	"fmt"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
)

// PostgresReader reads from the legacy Dialogue Postgres schema. It is
// strictly read-only — no INSERT/UPDATE/DELETE methods exist. Production
// deployments connect with the migrator_ro role.
type PostgresReader struct {
	pool *pgxpool.Pool
}

// NewPostgresReader opens a pgxpool against the legacy DSN.
// Callers must defer Close().
func NewPostgresReader(ctx context.Context, dsn string) (*PostgresReader, error) {
	if dsn == "" {
		return nil, errors.New("legacy: postgres dsn required")
	}
	pool, err := pgxpool.New(ctx, dsn)
	if err != nil {
		return nil, fmt.Errorf("legacy: open postgres pool: %w", err)
	}
	if err := pool.Ping(ctx); err != nil {
		pool.Close()
		return nil, fmt.Errorf("legacy: ping postgres: %w", err)
	}
	return &PostgresReader{pool: pool}, nil
}

// Close releases the underlying connection pool.
func (r *PostgresReader) Close() {
	if r.pool != nil {
		r.pool.Close()
	}
}

// ListChannels returns all legacy dialogue_channels rows for the given
// organization_id, ordered by id ASC for stable iteration.
func (r *PostgresReader) ListChannels(ctx context.Context, legacyOrgID string) ([]LegacyChannel, error) {
	if legacyOrgID == "" {
		return nil, errors.New("legacy: legacyOrgID required for ListChannels")
	}
	const q = `
SELECT id,
       organization_id,
       type,
       name,
       COALESCE(owner_user_id, ''),
       COALESCE(config, '{}'::jsonb)::text,
       COALESCE(is_default, false),
       created_at
  FROM dialogue_channels
 WHERE organization_id = $1
 ORDER BY id`

	rows, err := r.pool.Query(ctx, q, legacyOrgID)
	if err != nil {
		return nil, fmt.Errorf("legacy: ListChannels query: %w", err)
	}
	defer rows.Close()

	var out []LegacyChannel
	for rows.Next() {
		var ch LegacyChannel
		var configStr string
		var createdAt time.Time
		if err := rows.Scan(
			&ch.LegacyID,
			&ch.OrgID,
			&ch.Type,
			&ch.Name,
			&ch.OwnerUserID,
			&configStr,
			&ch.IsDefault,
			&createdAt,
		); err != nil {
			return nil, fmt.Errorf("legacy: ListChannels scan: %w", err)
		}
		ch.Config = []byte(configStr)
		ch.CreatedAt = createdAt.UTC()
		out = append(out, ch)
