	const gq = `
SELECT id, COALESCE(name, ''), COALESCE(description, ''), COALESCE(color, '')
  FROM contact_groups
 WHERE organization_id = $1
 ORDER BY id`

	rows, err := r.pool.Query(ctx, gq, legacyOrgID)
	if err != nil {
		return nil, fmt.Errorf("legacy: ListContactGroups query: %w", err)
	}
	defer rows.Close()

	groupIndex := map[string]int{}
	var groups []LegacyContactGroup
	for rows.Next() {
		var g LegacyContactGroup
		if err := rows.Scan(&g.LegacyID, &g.Name, &g.Description, &g.Color); err != nil {
			return nil, fmt.Errorf("legacy: ListContactGroups scan: %w", err)
		}
		groupIndex[g.LegacyID] = len(groups)
		groups = append(groups, g)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("legacy: ListContactGroups rows: %w", err)
	}
	if len(groups) == 0 {
		return nil, nil
	}

	const mq = `
SELECT group_id, contact_id, COALESCE(added_at, NOW())
  FROM contact_group_members
 WHERE organization_id = $1
 ORDER BY group_id, contact_id`

	mrows, err := r.pool.Query(ctx, mq, legacyOrgID)
	if err != nil {
		return nil, fmt.Errorf("legacy: ListContactGroups members query: %w", err)
	}
	defer mrows.Close()

	for mrows.Next() {
