		var addedAt time.Time
		if err := mrows.Scan(&groupID, &contactID, &addedAt); err != nil {
			return nil, fmt.Errorf("legacy: ListContactGroups members scan: %w", err)
		}
		if idx, ok := groupIndex[groupID]; ok {
			groups[idx].Members = append(groups[idx].Members, LegacyContactGroupMember{
				ContactLegacyID: contactID,
				AddedAt:         addedAt.UTC(),
			})
		}
	}
	if err := mrows.Err(); err != nil {
