// ListConversations returns all legacy conversations for the given org.
func (r *PostgresReader) ListConversations(ctx context.Context, legacyOrgID string) ([]LegacyConversation, error) {
	if legacyOrgID == "" {
		return nil, errors.New("legacy: legacyOrgID required for ListConversations")
	}
	const q = `
SELECT id, channel_id, COALESCE(is_group, false),
       COALESCE(contact_id, ''), COALESCE(external_thread_id, ''),
       COALESCE(title, ''), COALESCE(status, 'open'), COALESCE(priority, 0),
       COALESCE(last_message_at, created_at), created_at
  FROM conversations
 WHERE organization_id = $1
 ORDER BY id`

	rows, err := r.pool.Query(ctx, q, legacyOrgID)
	if err != nil {
		return nil, fmt.Errorf("legacy: ListConversations query: %w", err)
	}
	defer rows.Close()

	var out []LegacyConversation
	for rows.Next() {
		var c LegacyConversation
		var lastMsgAt, createdAt time.Time
		if err := rows.Scan(
			&c.LegacyID, &c.ChannelLegacyID, &c.IsGroup,
			&c.ContactLegacyID, &c.ExternalThreadID,
			&c.Title, &c.Status, &c.Priority,
			&lastMsgAt, &createdAt,
		); err != nil {
			return nil, fmt.Errorf("legacy: ListConversations scan: %w", err)
		}
		c.LastMessageAt = lastMsgAt.UTC()
		c.CreatedAt = createdAt.UTC()
		out = append(out, c)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("legacy: ListConversations rows: %w", err)
	}
	// Fetch group participants in a single batched query (avoids an N+1 over
	// group conversations). Collect the group conversation IDs and map each to
	// its index in out so rows can be grouped to the right conversation.
	var groupIDs []string
	idx := make(map[string]int, len(out))
	for i, conv := range out {
		if !conv.IsGroup {
			continue
		}
		groupIDs = append(groupIDs, conv.LegacyID)
		idx[conv.LegacyID] = i
	}
	if len(groupIDs) > 0 {
		const pq = `
SELECT conversation_id, contact_id
  FROM conversation_participants
 WHERE conversation_id = ANY($1)
 ORDER BY conversation_id, contact_id`
		prows, err := r.pool.Query(ctx, pq, groupIDs)
		if err != nil {
			return nil, fmt.Errorf("legacy: ListConversations participants: %w", err)
		}
		for prows.Next() {
			var convID, cid string
			if err := prows.Scan(&convID, &cid); err != nil {
				prows.Close()
				return nil, fmt.Errorf("legacy: ListConversations participants scan: %w", err)
			}
			i := idx[convID]
			out[i].ParticipantContactLegacyIDs = append(out[i].ParticipantContactLegacyIDs, cid)
		}
		prows.Close()
		if err := prows.Err(); err != nil {
			return nil, fmt.Errorf("legacy: ListConversations participants rows: %w", err)
		}
	}
	return out, nil
}

