package legacy_test

import (
	"context"
	"os"
	"path/filepath"
	"runtime"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
	"github.com/testcontainers/testcontainers-go"
	"github.com/testcontainers/testcontainers-go/modules/postgres"
	"github.com/testcontainers/testcontainers-go/wait"

	"github.com/zenithflowinc/omnicore-platform/services/migrator-dialogue/internal/legacy"
)

// fixtureDir returns the absolute path to the SQL fixtures directory.
func fixtureDir(t *testing.T) string {
	t.Helper()
	_, file, _, ok := runtime.Caller(0)
	require.True(t, ok)
	// pg_test.go is at internal/legacy/ — fixtures are at ../../tests/fixtures/
	return filepath.Join(filepath.Dir(file), "..", "..", "tests", "fixtures")
}

// startLegacyPostgres boots a testcontainers Postgres and applies the
// legacy_schema.sql fixture. Returns the DSN.
func startLegacyPostgres(t *testing.T) string {
	t.Helper()
	ctx := context.Background()

	fixturePath := filepath.Join(fixtureDir(t), "legacy_schema.sql")
	_, err := os.Stat(fixturePath)
	require.NoError(t, err, "legacy_schema.sql fixture must exist at %s", fixturePath)

	pgc, err := postgres.Run(ctx,
		"postgres:17-alpine",
		postgres.WithInitScripts(fixturePath),
		testcontainers.WithWaitStrategy(
			wait.ForLog("database system is ready to accept connections").WithOccurrence(2),
		),
	)
	require.NoError(t, err, "start legacy postgres testcontainer")
	t.Cleanup(func() {
		if err := pgc.Terminate(ctx); err != nil {
			t.Logf("warn: terminate postgres testcontainer: %v", err)
		}
	})

	dsn, err := pgc.ConnectionString(ctx, "sslmode=disable")
	require.NoError(t, err)
	return dsn
}

// TestPostgresReader_ListChannelsReturnsAllTypes boots a testcontainer
// Postgres, applies the fixture (1 email, 1 telegram_bot, 1 whatsapp),
// and asserts that ListChannels returns 3 rows. This is the A.0.2 gate.
func TestPostgresReader_ListChannelsReturnsAllTypes(t *testing.T) {
	if testing.Short() {
		t.Skip("integration test skipped in short mode")
	}
	ctx := context.Background()

	dsn := startLegacyPostgres(t)
	reader, err := legacy.NewPostgresReader(ctx, dsn)
	require.NoError(t, err)
	defer reader.Close()

	channels, err := reader.ListChannels(ctx, "legacy-org-001")
	require.NoError(t, err)

	assert.Len(t, channels, 3, "fixture seeds 3 channels for legacy-org-001")

	types := map[string]bool{}
	for _, ch := range channels {
		types[ch.Type] = true
	}
	assert.True(t, types["email"], "email channel must be present")
	assert.True(t, types["telegram_bot"], "telegram_bot channel must be present")
	assert.True(t, types["whatsapp"], "whatsapp channel must be present")
}

// TestPostgresReader_ListChannels_EmptyOrgReturnsError verifies that an
// empty org ID is rejected without hitting the database.
